add_filter( 'woocommerce_quantity_input_args', 'perfectpixel_quantity_rules_args', 20, 2 );
add_filter( 'woocommerce_available_variation', 'perfectpixel_quantity_rules_variation', 20, 3 );

/**
 * Product ID (or '*' for all) => [ default, min, max, step ]. Use 0 for "no change".
 */
function perfectpixel_quantity_rules_for( $product ) {
	$rules = array(
		'*' => array( 1, 1, 0, 1 ),
		// 123 => array( 6, 6, 60, 6 ),
	);
	$id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	return $rules[ $id ] ?? ( $rules['*'] ?? null );
}

function perfectpixel_quantity_rules_args( $args, $product ) {
	$rule = perfectpixel_quantity_rules_for( $product );
	if ( ! $rule ) {
		return $args;
	}
	list( $default, $min, $max, $step ) = $rule;
	if ( $min ) {
		$args['min_value'] = $min;
	}
	if ( $max ) {
		$args['max_value'] = $max;
	}
	if ( $step ) {
		$args['step'] = $step;
	}
	if ( $default && ! is_cart() ) {
		$args['input_value'] = $default;
	}
	return $args;
}

function perfectpixel_quantity_rules_variation( $data, $product, $variation ) {
	$rule = perfectpixel_quantity_rules_for( $variation );
	if ( $rule ) {
		if ( $rule[1] ) {
			$data['min_qty'] = $rule[1];
		}
		if ( $rule[2] ) {
			$data['max_qty'] = $rule[2];
		}
	}
	return $data;
}
